-- Migration 8: public codes for courses and students, and super-admin access
-- to transactions.
--
-- course_code   — a random, human-friendly id for every course (ABA-C-7K3Q9X),
--                 shown in the admin console and on receipts.
-- student_code  — a random permanent id for every account (ABA-S-4MZT8KQ2),
--                 shown in the app's Profile and the console's Students page.
-- Both are generated by the database, are unique, and can never be edited.
--
-- Transactions (orders and payments) are readable by the super admin only.
-- Granting or removing the super_admin role is also super-admin only.

-- ------------------------------------------------------------------ codes

-- Crockford-style alphabet: no 0/O or 1/I/L, so codes read aloud cleanly.
create or replace function public.random_code(prefix text, len integer)
returns text
language plpgsql
volatile
as $$
declare
  alphabet constant text := '23456789ABCDEFGHJKMNPQRSTUVWXYZ';
  result text := '';
begin
  for i in 1..len loop
    result := result || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
  end loop;
  return prefix || result;
end;
$$;

alter table public.courses
  add column if not exists course_code text not null default public.random_code('ABA-C-', 6);
create unique index if not exists courses_course_code_key on public.courses (course_code);

alter table public.profiles
  add column if not exists student_code text not null default public.random_code('ABA-S-', 8);
create unique index if not exists profiles_student_code_key on public.profiles (student_code);

create or replace function public.protect_codes()
returns trigger
language plpgsql
as $$
begin
  if tg_table_name = 'courses' and new.course_code is distinct from old.course_code then
    raise exception 'course_code cannot be changed' using errcode = '42501';
  end if;
  if tg_table_name = 'profiles' and new.student_code is distinct from old.student_code then
    raise exception 'student_code cannot be changed' using errcode = '42501';
  end if;
  return new;
end;
$$;

drop trigger if exists courses_protect_code on public.courses;
create trigger courses_protect_code
before update on public.courses
for each row execute function public.protect_codes();

drop trigger if exists profiles_protect_code on public.profiles;
create trigger profiles_protect_code
before update on public.profiles
for each row execute function public.protect_codes();

-- ------------------------------------------------------------ super admin

create or replace function public.is_super_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.role = 'super_admin'
  );
$$;

-- Same rule as before (admins may change roles, students may not), plus:
-- only a super admin may grant super_admin or change a super admin's role.
create or replace function public.protect_profile_role()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.role is distinct from old.role and auth.uid() is not null then
    if not public.is_admin() then
      raise exception 'Only an admin can change a profile role' using errcode = '42501';
    end if;
    if (new.role = 'super_admin' or old.role = 'super_admin')
       and not public.is_super_admin() then
      raise exception 'Only a super admin can grant or remove super admin'
        using errcode = '42501';
    end if;
  end if;
  return new;
end;
$$;

-- ------------------------------------------------------------ transactions

create policy "orders_super_admin_read"
on public.orders for select
using (public.is_super_admin());

create policy "payments_super_admin_read"
on public.payments for select
using (public.is_super_admin());
